DO $$ DECLARE f text; BEGIN f=pg_get_functiondef('public.pending_bell_push()'::regprocedure);
f=replace(f,'AND r.role IN (''superuser'',''admin'') WHERE s.status=''pending'' AND (s.supervisor_response IS NOT NULL OR s.consulted_supervisor_id IS NULL)','AND (r.role IN (''superuser'',''admin'') OR r.role=''supervisor'' AND public.has_role(s.user_id,''technician'')) WHERE s.status=''pending''');
f=replace(f,') SELECT e.key,e.user_id,e.title,e.url FROM events e','UNION ALL SELECT ''workspace-alert:''||a.id,a.recipient_id,a.title,CASE WHEN a.kind=''leave'' THEN CASE WHEN l.user_id=a.recipient_id THEN ''/leave?request='' ELSE ''/admin/leave?request='' END||a.record_id ELSE ''/pending-works?report=''||a.record_id||''&kind=''||a.kind END FROM public.workspace_thread_alerts a LEFT JOIN public.leave_requests l ON a.kind=''leave'' AND l.id=a.record_id JOIN recipients r ON r.user_id=a.recipient_id AND r.company_id=a.company_id WHERE a.seen_at IS NULL AND public.company_module_access(a.company_id,''core'') ) SELECT e.key,e.user_id,e.title,e.url FROM events e');
f=replace(f,'''/admin/jobs?new=true&assetId=''||s.asset_id||''&problemId=''||s.id','''/pending-works?kind=equipment&report=''||s.id'); f=replace(f,'''/admin/jobs?view=pending#store-report-''||s.id','''/pending-works?kind=store&report=''||s.id'); EXECUTE f; END $$;
CREATE OR REPLACE FUNCTION public.notify_leave_consultation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.consulted_supervisor_id IS DISTINCT FROM OLD.consulted_supervisor_id AND NEW.consulted_supervisor_id IS NOT NULL THEN INSERT INTO public.workspace_thread_alerts(company_id,recipient_id,kind,record_id,title) VALUES(NEW.company_id,NEW.consulted_supervisor_id,'leave',NEW.id,'Leave operational input requested'); END IF;
IF NEW.work_handling_note IS DISTINCT FROM OLD.work_handling_note AND coalesce(trim(NEW.work_handling_note),'')<>'' THEN INSERT INTO public.workspace_thread_messages(kind,record_id,body) VALUES('leave',NEW.id,NEW.work_handling_note); END IF;
IF NEW.supervisor_response IS DISTINCT FROM OLD.supervisor_response AND coalesce(trim(NEW.supervisor_response),'')<>'' THEN INSERT INTO public.workspace_thread_messages(kind,record_id,body) VALUES('leave',NEW.id,NEW.supervisor_response); END IF;
RETURN NEW;END $$;